package index

import (
	"regexp"
	"strings"

	"github.com/kljensen/snowball"
)

var wordBoundaryRegex = regexp.MustCompile(`[^\pL\pN]+`)

var stopWords = map[string]bool{
	"a":    true,
	"an":   true,
	"and":  true,
	"are":  true,
	"as":   true,
	"at":   true,
	"be":   true,
	"but":  true,
	"by":   true,
	"for":  true,
	"if":   true,
	"in":   true,
	"into": true,
	"is":   true,
	"it":   true,
	"no":   true,
	"not":  true,
	"of":   true,
	"on":   true,
	"or":   true,
	"such": true,
	"that": true,
	"the":  true,
	"their": true,
	"then": true,
	"there": true,
	"these": true,
	"they": true,
	"this": true,
	"to":   true,
	"was":  true,
	"were": true,
	"what": true,
	"when": true,
	"where": true,
	"which": true,
	"who":  true,
	"will": true,
	"with": true,
}

func Tokenize(text string) []string {
	lower := strings.ToLower(text)
	tokens := wordBoundaryRegex.Split(lower, -1)
	stemmed := make([]string, 0, len(tokens))
	for _, t := range tokens {
		if len(t) < 2 {
			continue
		}
		if stopWords[t] {
			continue
		}
		result, err := snowball.Stem(t, "english", true)
		if err != nil {
			stemmed = append(stemmed, t)
			continue
		}
		stemmed = append(stemmed, result)
	}
	return stemmed
}

var metaCharRegex = regexp.MustCompile(`[${}\[\]().*+?^|\\]`)

func StripMetaChars(query string) string {
	return metaCharRegex.ReplaceAllString(query, " ")
}

type SearchQuery struct {
	Phrase  string
	Tokens  []string
	RawText string
}

func ParseQuery(raw string) SearchQuery {
	var phrase string
	var phraseTokens []string

	for i, r := range raw {
		if r == '"' {
			end := strings.Index(raw[i+1:], "\"")
			if end >= 0 {
				phrase = raw[i+1 : i+1+end]
				phraseTokens = Tokenize(phrase)
				raw = raw[:i] + raw[i+1+end+1:]
				break
			}
		}
	}

	tokens := Tokenize(raw)
	if len(phraseTokens) > 0 {
		tokens = append(phraseTokens, tokens...)
	}

	return SearchQuery{
		Phrase:  phrase,
		Tokens:  tokens,
		RawText: raw,
	}
}

type ScoredEntry struct {
	Entry  PromptEntry
	Score  float64
	TruncatedMatch bool
}

func ScoreEntry(entry PromptEntry, query SearchQuery) ScoredEntry {
	if len(query.Tokens) == 0 {
		return ScoredEntry{Entry: entry, Score: 0}
	}

	promptTokens := Tokenize(entry.PromptText)
	promptTokenSet := make(map[string]bool)
	for _, t := range promptTokens {
		promptTokenSet[t] = true
	}

	score := 0.0

	if query.Phrase != "" && len(query.Tokens) > 0 {
		lowerPrompt := strings.ToLower(entry.PromptText)
		lowerPhrase := strings.ToLower(query.Phrase)
		if strings.Contains(lowerPrompt, lowerPhrase) {
			score += 10
		}
	}

	allFound := true
	for _, qt := range query.Tokens {
		if !promptTokenSet[qt] {
			allFound = false
			break
		}
	}
	if allFound && len(query.Tokens) > 0 {
		score += 5
	}

	anyFound := false
	matchCount := 0
	for _, qt := range query.Tokens {
		if promptTokenSet[qt] {
			anyFound = true
			matchCount++
		}
	}
	if anyFound {
		score += 1
	}

	if len(promptTokens) > 0 {
		termDensity := float64(matchCount) / float64(len(promptTokens))
		score += termDensity * 2
	}

	truncated := false
	if entry.PromptTruncated && anyFound {
		truncated = true
	}

	return ScoredEntry{
		Entry:          entry,
		Score:         score,
		TruncatedMatch: truncated,
	}
}

func Search(entries []PromptEntry, query SearchQuery, limit int) []ScoredEntry {
	scored := make([]ScoredEntry, 0, len(entries))
	for _, entry := range entries {
		result := ScoreEntry(entry, query)
		if result.Score > 0 {
			scored = append(scored, result)
		}
	}

	sortByScoreAndTime(scored)

	if limit > 0 && len(scored) > limit {
		scored = scored[:limit]
	}
	return scored
}

func sortByScoreAndTime(entries []ScoredEntry) {
	for i := 0; i < len(entries); i++ {
		for j := i + 1; j < len(entries); j++ {
			if entries[j].Score > entries[i].Score ||
				(entries[j].Score == entries[i].Score && entries[j].Entry.CreatedAt.After(entries[i].Entry.CreatedAt)) {
				entries[i], entries[j] = entries[j], entries[i]
			}
		}
	}
}

package index

import (
	"bufio"
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"sort"
	"strconv"
	"strings"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/paths"
)

const (
	IndexDirName  = "prompts"
	IndexFileName = "index.ndjson"
	LockFileName  = "index.lock"
)

var (
	ErrIndexMissing     = errors.New("prompt index not found")
	ErrIndexCorrupt      = errors.New("prompt index is corrupt")
	ErrIndexVersionNewer = errors.New("prompt index was created by a newer version of the CLI")
	ErrIndexEmpty        = errors.New("prompt index is empty")
)

type IndexStore struct {
	repoRoot string
	indexPath string
	lockPath string
}

func NewIndexStore(repoRoot string) *IndexStore {
	entireDir := filepath.Join(repoRoot, paths.EntireDir)
	indexDir := filepath.Join(entireDir, IndexDirName)
	return &IndexStore{
		repoRoot:  repoRoot,
		indexPath: filepath.Join(indexDir, IndexFileName),
		lockPath:  filepath.Join(indexDir, LockFileName),
	}
}

func (s *IndexStore) IndexPath() string {
	return s.indexPath
}

func (s *IndexStore) LockPath() string {
	return s.lockPath
}

func (s *IndexStore) IndexDir() string {
	return filepath.Dir(s.indexPath)
}

func (s *IndexStore) Exists() bool {
	_, err := os.Stat(s.indexPath)
	return err == nil
}

func (s *IndexStore) Load(ctx context.Context) (*IndexHeader, []PromptEntry, error) {
	if err := ctx.Err(); err != nil {
		return nil, nil, err
	}

	f, err := os.Open(s.indexPath)
	if err != nil {
		if os.IsNotExist(err) {
			return nil, nil, ErrIndexMissing
		}
		return nil, nil, fmt.Errorf("opening index: %w", err)
	}
	defer f.Close()

	scanner := bufio.NewScanner(f)
	var header IndexHeader
	var entries []PromptEntry
	lineNum := 0

	for scanner.Scan() {
		line := scanner.Bytes()
		if len(line) == 0 {
			continue
		}

		if lineNum == 0 {
			if err := json.Unmarshal(line, &header); err != nil {
				return nil, nil, fmt.Errorf("%w: malformed header: %v", ErrIndexCorrupt, err)
			}
			if header.Version > CurrentIndexVersion {
				return nil, nil, ErrIndexVersionNewer
			}
			if header.Version < CurrentIndexVersion {
				return nil, nil, fmt.Errorf("%w: version %d < %d", ErrIndexCorrupt, header.Version, CurrentIndexVersion)
			}
		} else {
			var entry PromptEntry
			if err := json.Unmarshal(line, &entry); err != nil {
				return nil, nil, fmt.Errorf("%w: line %d: %v", ErrIndexCorrupt, lineNum+1, err)
			}
			entries = append(entries, entry)
		}
		lineNum++
	}

	if err := scanner.Err(); err != nil {
		return nil, nil, fmt.Errorf("reading index: %w", err)
	}

	if lineNum == 0 {
		return nil, nil, ErrIndexEmpty
	}

	return &header, entries, nil
}

func (s *IndexStore) AppendEntry(entry PromptEntry) error {
	if err := os.MkdirAll(filepath.Dir(s.indexPath), 0o755); err != nil {
		return fmt.Errorf("creating index directory: %w", err)
	}

	lock, err := newLockFile(s.lockPath)
	if err != nil {
		return fmt.Errorf("creating lock: %w", err)
	}
	defer lock.Unlock()

	if err := lock.TryLock(); err != nil {
		return s.appendWithRetry(entry, 3)
	}

	return s.appendLine(entry)
}

func (s *IndexStore) appendLine(entry PromptEntry) error {
	data, err := json.Marshal(entry)
	if err != nil {
		return fmt.Errorf("marshaling entry: %w", err)
	}

	f, err := os.OpenFile(s.indexPath, os.O_APPEND|os.O_CREATE|os.O_WRONLY, 0o644)
	if err != nil {
		return fmt.Errorf("opening index for append: %w", err)
	}
	defer f.Close()

	if _, err := f.Write(append(data, '\n')); err != nil {
		return fmt.Errorf("appending to index: %w", err)
	}
	return nil
}

func (s *IndexStore) appendWithRetry(entry PromptEntry, maxRetries int) error {
	var lastErr error
	for i := 0; i < maxRetries; i++ {
		time.Sleep(50 * time.Millisecond)

		lock, err := newLockFile(s.lockPath)
		if err != nil {
			lastErr = err
			continue
		}
		defer lock.Unlock()

		if err := lock.TryLock(); err != nil {
			lastErr = err
			continue
		}

		if err := s.appendLine(entry); err != nil {
			lastErr = err
			continue
		}
		return nil
	}
	return fmt.Errorf("failed to acquire lock after %d retries: %w", maxRetries, lastErr)
}

func (s *IndexStore) InitIndex() error {
	if err := os.MkdirAll(filepath.Dir(s.indexPath), 0o755); err != nil {
		return fmt.Errorf("creating index directory: %w", err)
	}

	header := IndexHeader{
		Version:   CurrentIndexVersion,
		CreatedAt: time.Now(),
		RepoRoot:  s.repoRoot,
	}

	data, err := json.Marshal(header)
	if err != nil {
		return fmt.Errorf("marshaling header: %w", err)
	}

	if err := os.WriteFile(s.indexPath, append(data, '\n'), 0o644); err != nil {
		return fmt.Errorf("writing index header: %w", err)
	}

	return nil
}

func (s *IndexStore) Delete() error {
	if s.Exists() {
		if err := os.Remove(s.indexPath); err != nil {
			return fmt.Errorf("deleting index: %w", err)
		}
	}
	if _, err := os.Stat(s.lockPath); err == nil {
		if err := os.Remove(s.lockPath); err != nil {
			return fmt.Errorf("deleting lock: %w", err)
		}
	}
	return nil
}

func (s *IndexStore) WriteAll(header IndexHeader, entries []PromptEntry) error {
	if err := os.MkdirAll(filepath.Dir(s.indexPath), 0o755); err != nil {
		return fmt.Errorf("creating index directory: %w", err)
	}

	tmpPath := s.indexPath + ".tmp"
	f, err := os.Create(tmpPath)
	if err != nil {
		return fmt.Errorf("creating temp index: %w", err)
	}
	defer f.Close()

	header.CreatedAt = time.Now()
	header.RepoRoot = s.repoRoot

	headerData, err := json.Marshal(header)
	if err != nil {
		return fmt.Errorf("marshaling header: %w", err)
	}
	if _, err := f.Write(append(headerData, '\n')); err != nil {
		return fmt.Errorf("writing header: %w", err)
	}

	for _, entry := range entries {
		entryData, err := json.Marshal(entry)
		if err != nil {
			return fmt.Errorf("marshaling entry: %w", err)
		}
		if _, err := f.Write(append(entryData, '\n')); err != nil {
			return fmt.Errorf("writing entry: %w", err)
		}
	}

	if err := f.Close(); err != nil {
		return fmt.Errorf("closing temp index: %w", err)
	}

	if err := os.Rename(tmpPath, s.indexPath); err != nil {
		return fmt.Errorf("renaming temp index: %w", err)
	}

	return nil
}

func (s *IndexStore) Stats(ctx context.Context) (IndexStats, error) {
	header, entries, err := s.Load(ctx)
	if err != nil {
		if errors.Is(err, ErrIndexMissing) || errors.Is(err, ErrIndexEmpty) {
			return IndexStats{
				IndexPath: s.indexPath,
				Version:   CurrentIndexVersion,
				Exists:    s.Exists(),
			}, nil
		}
		return IndexStats{}, err
	}

	cpIDs := make(map[string]bool)
	for _, e := range entries {
		cpIDs[e.CheckpointID] = true
	}

	return IndexStats{
		IndexPath:    s.indexPath,
		Version:      header.Version,
		CheckpointCount: len(cpIDs),
		PromptCount:  len(entries),
		EmptyCount:   countEmptyPrompts(entries),
		FileSize:     fileSize(s.indexPath),
		LastUpdated:  header.CreatedAt,
		Exists:       true,
	}, nil
}

type IndexStats struct {
	IndexPath       string
	Version         int
	CheckpointCount int
	PromptCount     int
	EmptyCount      int
	FileSize        int64
	LastUpdated     time.Time
	Exists          bool
}

func (s *IndexStore) Verify(ctx context.Context, committedChecker func(ctx context.Context, cpID string) (bool, error)) (OrphanStats, error) {
	_, entries, err := s.Load(ctx)
	if err != nil {
		return OrphanStats{}, err
	}

	var orphans []string
	for _, e := range entries {
		exists, err := committedChecker(ctx, e.CheckpointID)
		if err != nil {
			return OrphanStats{}, err
		}
		if !exists {
			orphans = append(orphans, e.CheckpointID)
		}
	}

	return OrphanStats{
		TotalEntries:   len(entries),
		OrphanCount:     len(orphans),
		OrphanIDs:       orphans,
	}, nil
}

type OrphanStats struct {
	TotalEntries int
	OrphanCount  int
	OrphanIDs    []string
}

func countEmptyPrompts(entries []PromptEntry) int {
	count := 0
	for _, e := range entries {
		if strings.TrimSpace(e.PromptText) == "" {
			count++
		}
	}
	return count
}

func fileSize(path string) int64 {
	info, err := os.Stat(path)
	if err != nil {
		return 0
	}
	return info.Size()
}

func SortEntriesByTime(entries []PromptEntry) {
	sort.Slice(entries, func(i, j int) bool {
		return entries[j].CreatedAt.Before(entries[i].CreatedAt)
	})
}

func ParseCheckpointIDPrefix(prefix string) string {
	prefix = strings.TrimSpace(prefix)
	if len(prefix) > 12 {
		prefix = prefix[:12]
	}
	cpRegex := regexp.MustCompile(`^[0-9a-f]+`)
	matches := cpRegex.FindString(prefix)
	if len(matches) < 4 {
		return ""
	}
	return matches
}

type fileLock struct {
	path   string
	file   *os.File
	nfs    bool
}

func newLockFile(path string) (*fileLock, error) {
	return &fileLock{path: path}, nil
}

func (l *fileLock) TryLock() error {
	dir := filepath.Dir(l.path)
	if err := os.MkdirAll(dir, 0o755); err != nil {
		return err
	}

	var err error
	l.file, err = os.OpenFile(l.path, os.O_CREATE|os.EXCL|os.O_WRONLY, 0o644)
	if err != nil {
		if os.IsExist(err) {
			return fmt.Errorf("lock file already exists")
		}
		return err
	}
	return nil
}

func (l *fileLock) Unlock() error {
	if l.file != nil {
		l.file.Close()
		l.file = nil
	}
	os.Remove(l.path)
	return nil
}

