	}

	lock, err := newLockFile(s.lockPath)
	if err != nil {
		return fmt.Errorf("creating lock: %w", err)
	}
	defer lock.Unlock()

	if err := lock.TryLock(); err != nil {
		return s.appendWithRetry(entry, 3)
	}

	return s.appendLine(entry)
}

func (s *IndexStore) appendLine(entry PromptEntry) error {
	data, err := json.Marshal(entry)
	if err != nil {
		return fmt.Errorf("marshaling entry: %w", err)
	}

	f, err := os.OpenFile(s.indexPath, os.O_APPEND|os.O_CREATE|os.O_WRONLY, 0o644)
	if err != nil {
		return fmt.Errorf("opening index for append: %w", err)
	}
	defer f.Close()

	if _, err := f.Write(append(data, '\n')); err != nil {
		return fmt.Errorf("appending to index: %w", err)
	}
	return nil
}

func (s *IndexStore) appendWithRetry(entry PromptEntry, maxRetries int) error {
	var lastErr error
	for i := 0; i < maxRetries; i++ {
		time.Sleep(50 * time.Millisecond)

		lock, err := newLockFile(s.lockPath)
		if err != nil {
			lastErr = err
			continue
		}
		defer lock.Unlock()

		if err := lock.TryLock(); err != nil {
			lastErr = err
			continue
		}

		if err := s.appendLine(entry); err != nil {
			lastErr = err
			continue
		}
		return nil
	}
	return fmt.Errorf("failed to acquire lock after %d retries: %w", maxRetries, lastErr)
}

func (s *IndexStore) InitIndex() error {
	if err := os.MkdirAll(filepath.Dir(s.indexPath), 0o755); err != nil {
		return fmt.Errorf("creating index directory: %w", err)
	}

	header := IndexHeader{
		Version:   CurrentIndexVersion,
		CreatedAt: time.Now(),
		RepoRoot:  s.repoRoot,
	}

	data, err := json.Marshal(header)
	if err != nil {
		return fmt.Errorf("marshaling header: %w", err)
	}

	if err := os.WriteFile(s.indexPath, append(data, '\n'), 0o644); err != nil {
		return fmt.Errorf("writing index header: %w", err)
	}

	return nil
}

func (s *IndexStore) Delete() error {
	if s.Exists() {
		if err := os.Remove(s.indexPath); err != nil {
			return fmt.Errorf("deleting index: %w", err)
		}
	}
	if _, err := os.Stat(s.lockPath); err == nil {
		if err := os.Remove(s.lockPath); err != nil {
			return fmt.Errorf("deleting lock: %w", err)
		}
	}
	return nil
}

func (s *IndexStore) WriteAll(header IndexHeader, entries []PromptEntry) error {
	if err := os.MkdirAll(filepath.Dir(s.indexPath), 0o755); err != nil {
		return fmt.Errorf("creating index directory: %w", err)
	}

	tmpPath := s.indexPath + ".tmp"
	f, err := os.Create(tmpPath)
	if err != nil {
		return fmt.Errorf("creating temp index: %w", err)
	}
	defer f.Close()

	header.CreatedAt = time.Now()
	header.RepoRoot = s.repoRoot

	headerData, err := json.Marshal(header)
	if err != nil {
		return fmt.Errorf("marshaling header: %w", err)
	}
	if _, err := f.Write(append(headerData, '\n')); err != nil {
		return fmt.Errorf("writing header: %w", err)
	}

	for _, entry := range entries {
		entryData, err := json.Marshal(entry)
		if err != nil {
			return fmt.Errorf("marshaling entry: %w", err)
		}
		if _, err := f.Write(append(entryData, '\n')); err != nil {
			return fmt.Errorf("writing entry: %w", err)
		}
	}

	if err := f.Close(); err != nil {
		return fmt.Errorf("closing temp index: %w", err)
	}

	if err := os.Rename(tmpPath, s.indexPath); err != nil {
		return fmt.Errorf("renaming temp index: %w", err)
	}

	return nil
}

func (s *IndexStore) Stats(ctx context.Context) (IndexStats, error) {
	_, entries, err := s.Load(ctx)
	if err != nil {
		if errors.Is(err, ErrIndexMissing) || errors.Is(err, ErrIndexEmpty) {
			return IndexStats{
				IndexPath: s.indexPath,
				Version:   CurrentIndexVersion,
				Exists:    s.Exists(),
			}, nil
		}
		return IndexStats{}, err
	}

	cpIDs := make(map[string]bool)
	for _, e := range entries {
		cpIDs[e.CheckpointID] = true
	}

	return IndexStats{
		IndexPath:        s.indexPath,
		Version:          CurrentIndexVersion,
		CheckpointCount: len(cpIDs),
		PromptCount:     len(entries),
		EmptyCount:      countEmptyPrompts(entries),
		FileSize:        fileSize(s.indexPath),
		LastUpdated:      time.Now(),
		Exists:          true,
	}, nil
}

type IndexStats struct {
	IndexPath        string
	Version          int
	CheckpointCount  int
	PromptCount      int
	EmptyCount       int
	FileSize         int64
	LastUpdated      time.Time
	Exists           bool
}

func (s *IndexStore) Verify(ctx context.Context, checkpointExists func(ctx context.Context, cpID string) (bool, error)) (VerifyResult, error) {
	_, entries, err := s.Load(ctx)
	if err != nil {
		return VerifyResult{}, err
	}

	var orphans []string
	for _, e := range entries {
		exists, err := checkpointExists(ctx, e.CheckpointID)
		if err != nil {
			return VerifyResult{}, err
		}
		if !exists {
			orphans = append(orphans, e.CheckpointID)
		}
	}

	return VerifyResult{
		TotalEntries: len(entries),
		OrphanCount: len(orphans),
		OrphanIDs:   orphans,
	}, nil
}

type VerifyResult struct {
	TotalEntries int
	OrphanCount  int
	OrphanIDs    []string
}

func countEmptyPrompts(entries []PromptEntry) int {
	count := 0
	for _, e := range entries {
		if strings.TrimSpace(e.PromptText) == "" {
			count++
		}
	}
	return count
}

func fileSize(path string) int64 {
	info, err := os.Stat(path)
	if err != nil {
		return 0
	}
	return info.Size()
}

func SortEntriesByTime(entries []PromptEntry) {
	sort.Slice(entries, func(i, j int) bool {
		return entries[j].CreatedAt.Before(entries[i].CreatedAt)
	})
}

var checkpointIDPrefixRegex = regexp.MustCompile(`^[0-9a-f]{4,12}`)

func ParseCheckpointIDPrefix(prefix string) string {
	prefix = strings.TrimSpace(prefix)
	matches := checkpointIDPrefixRegex.FindString(prefix)
	if len(matches) < 4 {
		return ""
	}
	return matches
}

func FormatFileSize(bytes int64) string {
	if bytes < 1024 {
		return strconv.FormatInt(bytes, 10) + " B"
	}
	if bytes < 1024*1024 {
		return fmt.Sprintf("%.1f KB", float64(bytes)/1024)
	}
	return fmt.Sprintf("%.1f MB", float64(bytes)/(1024*1024))
}

type fileLock struct {
	path string
	file *os.File
}

func newLockFile(path string) (*fileLock, error) {
	return &fileLock{path: path}, nil
}

func (l *fileLock) TryLock() error {
	dir := filepath.Dir(l.path)
	if err := os.MkdirAll(dir, 0o755); err != nil {
		return err
	}

	var err error
	l.file, err = os.OpenFile(l.path, os.O_CREATE|os.EXCL|os.O_WRONLY, 0o644)
	if err != nil {
		if os.IsExist(err) {
			return errors.New("lock file already exists")
		}
		return err
	}
	return nil
}

func (l *fileLock) Unlock() error {
	if l.file != nil {
		l.file.Close()
		l.file = nil
	}
	os.Remove(l.path)
	return nil
}

package index

import (
	"context"
	"encoding/json"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"strconv"
	"strings"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/checkpoint"
	"github.com/entireio/cli/cmd/entire/cli/checkpoint/id"
	"github.com/entireio/cli/cmd/entire/cli/paths"

	"github.com/go-git/go-git/v6"
	"github.com/go-git/go-git/v6/plumbing"
)

const MaxPromptLength = 2000

type IndexBuilder struct {
	repo *git.Repository
	store *IndexStore
}

func NewIndexBuilder(repo *git.Repository, store *IndexStore) *IndexBuilder {
	return &IndexBuilder{
		repo:  repo,
		store: store,
	}
}

func (b *IndexBuilder) BuildFromTree(ctx context.Context, progress func(done, total int)) ([]PromptEntry, error) {
	ref, err := b.repo.Reference(plumbing.NewBranchReferenceName(paths.MetadataBranchName), true)
	if err != nil {
		return nil, fmt.Errorf("getting metadata branch: %w", err)
	}

	commit, err := b.repo.CommitObject(ref.Hash())
	if err != nil {
		return nil, fmt.Errorf("getting commit: %w", err)
	}

	tree, err := commit.Tree()
	if err != nil {
		return nil, fmt.Errorf("getting tree: %w", err)
	}

	var entries []PromptEntry
	var allEntries []string

	_ = WalkCheckpointShards(b.repo, tree, func(cpID id.CheckpointID, cpTreeHash plumbing.Hash) error {
		cpPath := string(cpID.Path())
		allEntries = append(allEntries, cpPath)
		return nil
	})

	total := len(allEntries)
	done := 0

	for _, cpEntry := range allEntries {
		cpEntries, err := b.loadCheckpointEntries(cpEntry)
		if err != nil {
			done++
			progress(done, total)
			continue
		}

		for _, ce := range cpEntries {
			entries = append(entries, ce)
		}

		done++
		if progress != nil {
			progress(done, total)
		}
	}

	return entries, nil
}

func (b *IndexBuilder) loadCheckpointEntries(cpPath string) ([]PromptEntry, error) {
	parts := strings.Split(cpPath, "/")
	if len(parts) != 2 {
		return nil, fmt.Errorf("invalid checkpoint path: %s", cpPath)
	}

	bucketDir := parts[0]
	cpDir := parts[1]

	bucketTree, err := b.repo.TreeObject(plumbing.NewHash(plumbing.HashSize))
	_ = bucketTree

	bucketHashStr := ""
	for _, e := range b.walkBuckets() {
		if e.Name == bucketDir {
			bucketHashStr = e.Hash.String()
			break
		}
	}
	if bucketHashStr == "" {
		return nil, fmt.Errorf("bucket not found: %s", bucketDir)
	}

	bucketHash := plumbing.NewHash(bucketHashStr)
	bucketTree, err = b.repo.TreeObject(bucketHash)
	if err != nil {
		return nil, fmt.Errorf("getting bucket tree: %w", err)
	}

	var cpHash plumbing.Hash
	for _, e := range bucketTree.Entries {
		if e.Name == cpDir {
			cpHash = e.Hash
			break
		}
	}
	if cpHash.IsZero() {
		return nil, fmt.Errorf("checkpoint not found: %s", cpDir)
	}

	cpTree, err := b.repo.TreeObject(cpHash)
	if err != nil {
		return nil, fmt.Errorf("getting checkpoint tree: %w", err)
	}

	metaFile, err := cpTree.File(paths.MetadataFileName)
	if err != nil {
		return nil, fmt.Errorf("reading checkpoint metadata: %w", err)
	}

	metaContent, err := metaFile.Contents()
	if err != nil {
		return nil, fmt.Errorf("reading metadata content: %w", err)
	}

	var summary checkpoint.CheckpointSummary
	if err := json.Unmarshal([]byte(metaContent), &summary); err != nil {
		return nil, fmt.Errorf("parsing checkpoint summary: %w", err)
	}

	entries := make([]PromptEntry, 0)

	for i, sessionPath := range summary.Sessions {
		entries = append(entries, b.loadSessionEntry(cpPath, i, sessionPath.Metadata, summary)...)
	}

	_ = entries
	return entries, nil
}

func (b *IndexBuilder) loadSessionEntry(cpPath string, sessionIndex int, sessionMetaPath string, summary checkpoint.CheckpointSummary) []PromptEntry {
	var entries []PromptEntry

	cpParts := strings.Split(cpPath, "/")
	if len(cpParts) != 2 {
		return nil
	}
	cpID := cpParts[1]

	entry := PromptEntry{
		CheckpointID:    cpID,
		SessionIndex:    sessionIndex,
		TurnIndex:       0,
		Kind:            "session",
		PromptText:      "",
		PromptTruncated: false,
		Branch:          summary.Branch,
		FilesTouched:    summary.FilesTouched,
		CreatedAt:      time.Now(),
	}

	if sessionMetaPath != "" {
		metaParts := strings.Split(sessionMetaPath, "/")
		if len(metaParts) >= 3 {
			sessionDir := metaParts[len(metaParts)-2]
			if sessionIdx, err := strconv.Atoi(sessionDir); err == nil {
				entry.SessionIndex = sessionIdx
			}
		}
	}

	entries = append(entries, entry)
	return entries
}

func (b *IndexBuilder) walkBuckets() []plumbing.TreeEntry {
	ref, err := b.repo.Reference(plumbing.NewBranchReferenceName(paths.MetadataBranchName), true)
	if err != nil {
		return nil
	}
	commit, err := b.repo.CommitObject(ref.Hash())
	if err != nil {
		return nil
	}
	tree, err := commit.Tree()
	if err != nil {
		return nil
	}
	return tree.Entries
}

type progressFunc func(done, total int)

func WalkCheckpointShards(repo *git.Repository, tree plumbing.Object, fn func(id.CheckpointID, plumbing.Hash) error) error {
	iter := tree.Files()
	defer iter.Close()

	var shardEntries []plumbing.TreeEntry

	rootTree, ok := tree.(*object.Tree)
	if ok {
		for _, e := range rootTree.Entries {
			if e.Mode.IsDir() && len(e.Name) == 2 && isHex(e.Name) {
				shardEntries = append(shardEntries, e)
			}
		}
	}

	for _, shard := range shardEntries {
		shardTree, err := repo.TreeObject(shard.Hash)
		if err != nil {
			continue
		}

		for _, cpEntry := range shardTree.Entries {
			if cpEntry.Mode.IsDir() && isHex(cpEntry.Name) {
				fullID := shard.Name + cpEntry.Name
				cpID, err := id.NewCheckpointID(fullID)
				if err != nil {
					continue
				}
				if err := fn(cpID, cpEntry.Hash); err != nil {
					return err
				}
			}
		}
	}

	return nil
}

func isHex(s string) bool {
	for _, c := range s {
		if !((c >= '0' && c <= '9') || (c >= 'a' && c <= 'f')) {
			return false
		}
	}
	return len(s) > 0
}

func (b *IndexBuilder) AppendFromCheckpoint(ctx context.Context, cpID string, sessionIndex int, data SessionData) error {
	promptText := data.PromptText
	promptTruncated := false

	if len(promptText) > MaxPromptLength {
		promptText = promptText[:MaxPromptLength]
		promptTruncated = true
	}

	entry := PromptEntry{
		CheckpointID:    cpID,
		SessionIndex:    sessionIndex,
		TurnIndex:       0,
		Kind:            data.Kind,
		PromptText:      promptText,
		PromptTruncated: promptTruncated,
		CommitHash:      data.CommitHash,
		CommitMessage:   data.CommitMessage,
		Branch:          data.Branch,
		Agent:           data.Agent,
		Model:           data.Model,
		TokenCount:      data.TokenCount,
		FilesTouched:    data.FilesTouched,
		CreatedAt:      data.CreatedAt,
	}

	return b.store.AppendEntry(entry)
}

type SessionData struct {
	PromptText     string
	Kind           string
	CommitHash     string
	CommitMessage  string
	Branch         string
	Agent          string
	Model          string
	TokenCount     int
	FilesTouched   []string
	CreatedAt      time.Time
}

func SplitMultiTurnPrompt(promptContent string) []string {
	if strings.TrimSpace(promptContent) == "" {
		return nil
	}

	turns := strings.Split(promptContent, "\n\n---\n\n")
	result := make([]string, 0, len(turns))

	for _, turn := range turns {
		trimmed := strings.TrimSpace(turn)
		if trimmed != "" {
			result = append(result, trimmed)
		}
	}

	return result
}

func (b *IndexBuilder) BuildFromGit(ctx context.Context, out io.Writer, progress progressFunc) error {
	if !b.store.Exists() {
		if err := b.store.InitIndex(); err != nil {
			return fmt.Errorf("initializing index: %w", err)
		}
	}

	entries, err := b.BuildFromTree(ctx, progress)
	if err != nil {
		return fmt.Errorf("building index: %w", err)
	}

	header := IndexHeader{
		Version:   CurrentIndexVersion,
		CreatedAt: time.Now(),
		RepoRoot:  b.store.repoRoot,
	}

	if err := b.store.WriteAll(header, entries); err != nil {
		return fmt.Errorf("writing index: %w", err)
	}

	fmt.Fprintf(out, "Indexed %d prompts from %d checkpoints.\n", len(entries), countUniqueCheckpoints(entries))
	return nil
}

func countUniqueCheckpoints(entries []PromptEntry) int {
	seen := make(map[string]bool)
	count := 0
	for _, e := range entries {
		if !seen[e.CheckpointID] {
			seen[e.CheckpointID] = true
			count++
		}
	}
	return count
}

import "github.com/go-git/go-git/v6/plumbing/object"

package index

import (
	"context"
	"encoding/json"
	"fmt"
	"io"
	"path/filepath"
	"strconv"
	"strings"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/checkpoint"
	"github.com/entireio/cli/cmd/entire/cli/checkpoint/id"
	"github.com/entireio/cli/cmd/entire/cli/paths"

	"github.com/go-git/go-git/v6"
	"github.com/go-git/go-git/v6/plumbing"
	"github.com/go-git/go-git/v6/plumbing/object"
)

const MaxPromptLength = 2000

type IndexBuilder struct {
	repo  *git.Repository
	store *IndexStore
}

func NewIndexBuilder(repo *git.Repository, store *IndexStore) *IndexBuilder {
	return &IndexBuilder{repo: repo, store: store}
}

func (b *IndexBuilder) Build(ctx context.Context, out io.Writer, progress func(done, total int)) error {
	if err := b.store.InitIndex(); err != nil {
		return fmt.Errorf("initializing index: %w", err)
	}

	ref, err := b.repo.Reference(plumbing.NewBranchReferenceName(paths.MetadataBranchName), true)
	if err != nil {
		return fmt.Errorf("getting metadata branch: %w", err)
	}

	commit, err := b.repo.CommitObject(ref.Hash())
	if err != nil {
		return fmt.Errorf("getting commit: %w", err)
	}

	tree, err := commit.Tree()
	if err != nil {
		return fmt.Errorf("getting tree: %w", err)
	}

	var cpIDs []id.CheckpointID
	_ = walkCheckpointShards(b.repo, tree, func(cpID id.CheckpointID, _ plumbing.Hash) error {
		cpIDs = append(cpIDs, cpID)
		return nil
	})

	total := len(cpIDs)
	allEntries := make([]PromptEntry, 0)

	for i, cpID := range cpIDs {
		entries, _ := b.loadCheckpoint(cpID)
		allEntries = append(allEntries, entries...)
		if progress != nil {
			progress(i+1, total)
		}
	}

	header := IndexHeader{
		Version:   CurrentIndexVersion,
		CreatedAt: time.Now(),
		RepoRoot:  b.store.repoRoot,
	}

	if err := b.store.WriteAll(header, allEntries); err != nil {
		return fmt.Errorf("writing index: %w", err)
	}

	fmt.Fprintf(out, "Indexed %d prompts from %d checkpoints.\n", len(allEntries), len(cpIDs))
	return nil
}

func (b *IndexBuilder) loadCheckpoint(cpID id.CheckpointID) ([]PromptEntry, error) {
	ref, err := b.repo.Reference(plumbing.NewBranchReferenceName(paths.MetadataBranchName), true)
	if err != nil {
		return nil, err
	}
	commit, err := b.repo.CommitObject(ref.Hash())
	if err != nil {
		return nil, err
	}
	tree, err := commit.Tree()
	if err != nil {
		return nil, err
	}

	cpPath := cpID.Path()
	cpTree, err := tree.Tree(cpPath)
	if err != nil {
		return nil, fmt.Errorf("checkpoint tree not found: %w", err)
	}

	metaFile, err := cpTree.File(paths.MetadataFileName)
	if err != nil {
		return nil, fmt.Errorf("reading checkpoint metadata: %w", err)
	}
	metaContent, err := metaFile.Contents()
	if err != nil {
		return nil, err
	}

	var summary checkpoint.CheckpointSummary
	if err := json.Unmarshal([]byte(metaContent), &summary); err != nil {
		return nil, err
	}

	entries := make([]PromptEntry, 0, len(summary.Sessions))

	for i, sessionPaths := range summary.Sessions {
		sessionEntries, err := b.loadSession(cpID, i, sessionPaths, summary)
		if err != nil {
			continue
		}
		entries = append(entries, sessionEntries...)
	}

	return entries, nil
}

func (b *IndexBuilder) loadSession(cpID id.CheckpointID, sessionIndex int, sessionPaths checkpoint.SessionFilePaths, summary checkpoint.CheckpointSummary) ([]PromptEntry, error) {
	ref, err := b.repo.Reference(plumbing.NewBranchReferenceName(paths.MetadataBranchName), true)
	if err != nil {
		return nil, err
	}
	commit, err := b.repo.CommitObject(ref.Hash())
	if err != nil {
		return nil, err
	}
	tree, err := commit.Tree()
	if err != nil {
		return nil, err
	}

	cpTree, err := tree.Tree(cpID.Path())
	if err != nil {
		return nil, err
	}

	sessionDir := strconv.Itoa(sessionIndex)
	sessionTree, err := cpTree.Tree(sessionDir)
	if err != nil {
		return nil, err
	}

	var metadata checkpoint.CommittedMetadata
	if metaFile, err := sessionTree.File(paths.MetadataFileName); err == nil {
		if metaContent, err := metaFile.Contents(); err == nil {
			json.Unmarshal([]byte(metaContent), &metadata)
		}
	}

	var promptText string
	var promptTruncated bool
	if promptFile, err := sessionTree.File(paths.PromptFileName); err == nil {
		if content, err := promptFile.Contents(); err == nil {
			if len(content) > MaxPromptLength {
				promptText = content[:MaxPromptLength]
				promptTruncated = true
			} else {
				promptText = content
			}
		}
	}

	turns := splitMultiTurn(promptText)
	entries := make([]PromptEntry, 0, len(turns))

	for turnIdx, turnText := range turns {
		if strings.TrimSpace(turnText) == "" {
			continue
		}
		entries = append(entries, PromptEntry{
			CheckpointID:     string(cpID),
			SessionIndex:     sessionIndex,
			TurnIndex:        turnIdx,
			Kind:             metadata.Kind,
			PromptText:       turnText,
			PromptTruncated:  promptTruncated && turnIdx == len(turns)-1,
			CommitHash:       "",
			CommitMessage:    "",
			Branch:           summary.Branch,
			Agent:            string(metadata.Agent),
			Model:            metadata.Model,
			TokenCount:       0,
			FilesTouched:     summary.FilesTouched,
			CreatedAt:        metadata.CreatedAt,
		})
	}

	return entries, nil
}

func splitMultiTurn(promptContent string) []string {
	if strings.TrimSpace(promptContent) == "" {
		return nil
	}
	turns := strings.Split(promptContent, "\n\n---\n\n")
	result := make([]string, 0, len(turns))
	for _, turn := range turns {
		if trimmed := strings.TrimSpace(turn); trimmed != "" {
			result = append(result, trimmed)
		}
	}
	if len(result) == 0 {
		return []string{promptContent}
	}
	return result
}

func walkCheckpointShards(repo *git.Repository, tree plumbing.Object, fn func(id.CheckpointID, plumbing.Hash) error) error {
	rootTree, ok := tree.(*object.Tree)
	if !ok {
		return fmt.Errorf("not a tree object")
	}

	for _, shardEntry := range rootTree.Entries {
		if !shardEntry.Mode.IsDir() || len(shardEntry.Name) != 2 || !isHex(shardEntry.Name) {
			continue
		}

		shardTree, err := repo.TreeObject(shardEntry.Hash)
		if err != nil {
			continue
		}

		for _, cpEntry := range shardTree.Entries {
			if !cpEntry.Mode.IsDir() || len(cpEntry.Name) != 10 || !isHex(cpEntry.Name) {
				continue
			}

			fullID := shardEntry.Name + cpEntry.Name
			cpID, err := id.NewCheckpointID(fullID)
			if err != nil {
				continue
			}

			if err := fn(cpID, cpEntry.Hash); err != nil {
				return err
			}
		}
	}

	return nil
}

func isHex(s string) bool {
	for _, c := range s {
		if !((c >= '0' && c <= '9') || (c >= 'a' && c <= 'f')) {
			return false
		}
	}
	return len(s) > 0
}

type SessionData struct {
	PromptText    string
	Kind          string
	CommitHash    string
	CommitMessage string
	Branch        string
	Agent         string
	Model         string
	TokenCount    int
	FilesTouched  []string
	CreatedAt     time.Time
}

func (b *IndexBuilder) AppendFromCheckpoint(ctx context.Context, cpID string, sessionIndex int, data SessionData) error {
	truncated := false
	promptText := data.PromptText
	if len(promptText) > MaxPromptLength {
		promptText = promptText[:MaxPromptLength]
		truncated = true
	}

	turns := splitMultiTurn(promptText)
	for turnIdx, turnText := range turns {
		if strings.TrimSpace(turnText) == "" {
			continue
		}
		entry := PromptEntry{
			CheckpointID:    cpID,
			SessionIndex:     sessionIndex,
			TurnIndex:        turnIdx,
			Kind:             data.Kind,
			PromptText:       turnText,
			PromptTruncated:  truncated && turnIdx == len(turns)-1,
			CommitHash:       data.CommitHash,
			CommitMessage:    data.CommitMessage,
			Branch:           data.Branch,
			Agent:            data.Agent,
			Model:            data.Model,
			TokenCount:       data.TokenCount,
			FilesTouched:     data.FilesTouched,
			CreatedAt:        data.CreatedAt,
		}
		if err := b.store.AppendEntry(entry); err != nil {
			return err
		}
	}
	return nil
}

