package index

import (
	"testing"
)

func TestTokenize(t *testing.T) {
	t.Parallel()

	tests := []struct {
		input    string
		expected []string
	}{
		{"hello world", []string{"hello", "world"}},
		{"The quick brown fox", []string{"quick", "brown", "fox"}},
		{"authentication", []string{"authent"}},
		{"caching", []string{"cache"}},
		{"", []string{}},
		{"a", []string{}},
		{"ab", []string{"ab"}},
	}

	for _, tt := range tests {
		result := Tokenize(tt.input)
		if len(result) != len(tt.expected) {
			t.Errorf("Tokenize(%q) = %v, want %v", tt.input, result, tt.expected)
			continue
		}
		for i := range result {
			if result[i] != tt.expected[i] {
				t.Errorf("Tokenize(%q)[%d] = %v, want %v", tt.input, i, result[i], tt.expected[i])
			}
		}
	}
}

func TestParseQuery(t *testing.T) {
	t.Parallel()

	tests := []struct {
		input       string
		wantPhrase  string
		wantTokens  int
	}{
		{"cache decision", "", 2},
		{`"cache decision"`, "cache decision", 2},
		{"hello", "", 1},
		{"the hello", "hello", 1},
		{"", "", 0},
	}

	for _, tt := range tests {
		q := ParseQuery(tt.input)
		if tt.wantPhrase != "" && q.Phrase != tt.wantPhrase {
			t.Errorf("ParseQuery(%q).Phrase = %q, want %q", tt.input, q.Phrase, tt.wantPhrase)
		}
		if len(q.Tokens) != tt.wantTokens {
			t.Errorf("ParseQuery(%q) tokens = %d, want %d", tt.input, len(q.Tokens), tt.wantTokens)
		}
	}
}

func TestScoreEntry(t *testing.T) {
	t.Parallel()

	entry := PromptEntry{
		PromptText: "I need to add caching to improve performance",
	}

	query := ParseQuery("cache performance")

	result := ScoreEntry(entry, query)
	if result.Score <= 0 {
		t.Errorf("ScoreEntry() = %v, want > 0", result.Score)
	}
}

func TestSearchWithFilters(t *testing.T) {
	t.Parallel()

	entries := []PromptEntry{
		{CheckpointID: "abc123", Agent: "claude-code", Branch: "main", Kind: "session", PromptText: "add caching", CreatedAt: time.Now().Add(-1)},
		{CheckpointID: "def456", Agent: "gemini", Branch: "main", Kind: "session", PromptText: "fix bug", CreatedAt: time.Now()},
