package index

import (
	"time"
)

const CurrentIndexVersion = 1

type IndexHeader struct {
	Version   int       `json:"version"`
	CreatedAt time.Time `json:"created_at"`
	RepoRoot  string    `json:"repo_root"`
}

type PromptEntry struct {
	CheckpointID    string    `json:"checkpoint_id"`
	SessionIndex    int       `json:"session_index"`
	TurnIndex       int       `json:"turn_index"`
	Kind            string    `json:"kind"`
	PromptText      string    `json:"prompt_text"`
	PromptTruncated bool      `json:"prompt_truncated"`
	CommitHash      string    `json:"commit_hash"`
	CommitMessage   string    `json:"commit_message"`
	Branch          string    `json:"branch"`
	Agent           string    `json:"agent"`
	Model           string    `json:"model"`
	TokenCount      int       `json:"token_count"`
	ParentCheckpointID string `json:"parent_checkpoint_id,omitempty"`
	SubagentDepth   int       `json:"subagent_depth"`
	FilesTouched    []string  `json:"files_touched"`
	CreatedAt       time.Time `json:"created_at"`
}

type SearchConfig struct {
	Query   string
	Limit   int
	JSON    bool
	Agent   string
	Branch  string
	Kind    string
	After   string
	Files   string
}

func ParseCheckpointIDPrefix(s string) string {
	if len(s) < 4 || len(s) > 12 {
		return ""
	}
	for _, c := range s {
		if !((c >= '0' && c <= '9') || (c >= 'a' && c <= 'f')) {
			return ""
		}
	}
	return s
}

package index

import (
	"regexp"
	"sort"
	"strings"
	"time"

	"github.com/kljensen/snowball"
)

var wordBoundaryRegex = regexp.MustCompile(`[^\pL\pN]+`)

var stopWords = map[string]bool{
	"a": true, "an": true, "and": true, "are": true, "as": true, "at": true,
	"be": true, "but": true, "by": true, "for": true, "if": true, "in": true,
	"into": true, "is": true, "it": true, "no": true, "not": true, "of": true,
	"on": true, "or": true, "such": true, "that": true, "the": true,
	"their": true, "then": true, "there": true, "these": true, "they": true,
	"this": true, "to": true, "was": true, "were": true, "what": true,
	"when": true, "where": true, "which": true, "who": true, "will": true, "with": true,
}

func Tokenize(text string) []string {
	lower := strings.ToLower(text)
	tokens := wordBoundaryRegex.Split(lower, -1)
	stemmed := make([]string, 0, len(tokens))
	for _, t := range tokens {
		if len(t) < 2 {
			continue
		}
		if stopWords[t] {
			continue
		}
		result, err := snowball.Stem(t, "english", true)
		if err != nil {
			stemmed = append(stemmed, t)
			continue
		}
		stemmed = append(stemmed, result)
	}
	return stemmed
}

var metaCharRegex = regexp.MustCompile(`[${}\[\]().*+?^|\\]`)

func StripMetaChars(query string) string {
	return metaCharRegex.ReplaceAllString(query, " ")
}

type SearchQuery struct {
	Phrase  string
	Tokens  []string
	RawText string
}

func ParseQuery(raw string) SearchQuery {
	var phrase string
	var phraseTokens []string

	for i, r := range raw {
		if r == '"' {
			end := strings.Index(raw[i+1:], "\"")
			if end >= 0 {
				phrase = raw[i+1 : i+1+end]
				phraseTokens = Tokenize(phrase)
				raw = raw[:i] + raw[i+1+end+1:]
				break
			}
		}
	}

	tokens := Tokenize(raw)
	if len(phraseTokens) > 0 {
		tokens = append(phraseTokens, tokens...)
	}

	return SearchQuery{
		Phrase:  phrase,
		Tokens:  tokens,
		RawText: raw,
	}
}

type ScoredEntry struct {
	Entry          PromptEntry
	Score          float64
	TruncatedMatch bool
}

func ScoreEntry(entry PromptEntry, query SearchQuery) ScoredEntry {
	if len(query.Tokens) == 0 {
		return ScoredEntry{Entry: entry, Score: 0}
	}

	promptTokens := Tokenize(entry.PromptText)
	promptTokenSet := make(map[string]bool)
	for _, t := range promptTokens {
		promptTokenSet[t] = true
	}

	score := 0.0

	if query.Phrase != "" && len(query.Tokens) > 0 {
		lowerPrompt := strings.ToLower(entry.PromptText)
		lowerPhrase := strings.ToLower(query.Phrase)
		if strings.Contains(lowerPrompt, lowerPhrase) {
			score += 10
		}
	}

	allFound := true
	for _, qt := range query.Tokens {
		if !promptTokenSet[qt] {
			allFound = false
			break
		}
	}
	if allFound && len(query.Tokens) > 0 {
		score += 5
	}

	anyFound := false
	matchCount := 0
	for _, qt := range query.Tokens {
		if promptTokenSet[qt] {
			anyFound = true
			matchCount++
		}
	}
	if anyFound {
		score++
	}

	if len(promptTokens) > 0 {
		termDensity := float64(matchCount) / float64(len(promptTokens))
		score += termDensity * 2
	}

	truncated := false
	if entry.PromptTruncated && anyFound {
		truncated = true
	}

	return ScoredEntry{
		Entry:          entry,
		Score:         score,
		TruncatedMatch: truncated,
	}
}

func Search(entries []PromptEntry, cfg SearchConfig) []ScoredEntry {
	query := ParseQuery(cfg.Query)

	scored := make([]ScoredEntry, 0, len(entries))
	for _, entry := range entries {
		if !matchesFilter(entry, cfg) {
			continue
		}
		result := ScoreEntry(entry, query)
		if result.Score > 0 {
			scored = append(scored, result)
		}
	}

	sortByScoreAndTime(scored)

	if cfg.Limit > 0 && len(scored) > cfg.Limit {
		scored = scored[:cfg.Limit]
	}
	return scored
}

func matchesFilter(entry PromptEntry, cfg SearchConfig) bool {
	if cfg.Agent != "" && !strings.EqualFold(entry.Agent, cfg.Agent) {
		return false
	}
	if cfg.Branch != "" && !strings.EqualFold(entry.Branch, cfg.Branch) {
		return false
	}
	if cfg.Kind != "" && !strings.EqualFold(entry.Kind, cfg.Kind) {
		return false
	}
	if cfg.After != "" {
		if t, err := time.Parse("2006-01-02", cfg.After); err == nil {
			if entry.CreatedAt.Before(t) {
				return false
			}
		}
	}
	if cfg.Files != "" {
		found := false
		fileFilter := strings.ToLower(cfg.Files)
		for _, f := range entry.FilesTouched {
			if strings.Contains(strings.ToLower(f), fileFilter) {
				found = true
				break
			}
		}
		if !found {
			return false
		}
	}
	return true
}

func sortByScoreAndTime(entries []ScoredEntry) {
	for i := 0; i < len(entries); i++ {
		for j := i + 1; j < len(entries); j++ {
			if entries[j].Score > entries[i].Score ||
				(entries[j].Score == entries[i].Score && entries[j].Entry.CreatedAt.After(entries[i].Entry.CreatedAt)) {
				entries[i], entries[j] = entries[j], entries[i]
			}
		}
	}
}

package index

import (
	"bufio"
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"regexp"
	"sort"
	"strconv"
	"strings"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/paths"
)

const (
	IndexDirName  = "prompts"
	IndexFileName = "index.ndjson"
	LockFileName  = "index.lock"
)

var (
	ErrIndexMissing      = errors.New("prompt index not found")
	ErrIndexCorrupt      = errors.New("prompt index is corrupt")
	ErrIndexVersionNewer = errors.New("prompt index was created by a newer version of the CLI")
	ErrIndexEmpty        = errors.New("prompt index is empty")
)

type IndexStore struct {
	repoRoot  string
	indexPath string
	lockPath  string
}

func NewIndexStore(repoRoot string) *IndexStore {
	entireDir := filepath.Join(repoRoot, paths.EntireDir)
	indexDir := filepath.Join(entireDir, IndexDirName)
	return &IndexStore{
		repoRoot:  repoRoot,
		indexPath: filepath.Join(indexDir, IndexFileName),
		lockPath:  filepath.Join(indexDir, LockFileName),
	}
}

func (s *IndexStore) IndexPath() string { return s.indexPath }
func (s *IndexStore) LockPath() string  { return s.lockPath }
func (s *IndexStore) IndexDir() string   { return filepath.Dir(s.indexPath) }

func (s *IndexStore) Exists() bool {
	_, err := os.Stat(s.indexPath)
	return err == nil
}

func (s *IndexStore) Load(ctx context.Context) (*IndexHeader, []PromptEntry, error) {
	f, err := os.Open(s.indexPath)
	if err != nil {
		if os.IsNotExist(err) {
			return nil, nil, ErrIndexMissing
		}
		return nil, nil, err
	}
	defer f.Close()

	scanner := bufio.NewScanner(f)
	var header IndexHeader
	var entries []PromptEntry
	lineNum := 0

	for scanner.Scan() {
		line := strings.TrimSpace(scanner.Text())
		if line == "" {
			lineNum++
			continue
		}

		if lineNum == 0 {
			if err := json.Unmarshal([]byte(line), &header); err != nil {
				return nil, nil, fmt.Errorf("%w: header: %v", ErrIndexCorrupt, err)
			}
		} else {
			var entry PromptEntry
			if err := json.Unmarshal([]byte(line), &entry); err != nil {
				return nil, nil, fmt.Errorf("%w: line %d: %v", ErrIndexCorrupt, lineNum+1, err)
			}
			entries = append(entries, entry)
		}
		lineNum++
	}

	if err := scanner.Err(); err != nil {
		return nil, nil, err
	}

	if lineNum == 0 {
		return nil, nil, ErrIndexEmpty
	}

	return &header, entries, nil
}

func (s *IndexStore) AppendEntries(entries []PromptEntry) error {
	if len(entries) == 0 {
		return nil
	}

	if err := os.MkdirAll(filepath.Dir(s.indexPath), 0o750); err != nil {
		return fmt.Errorf("creating index directory: %w", err)
	}

	lock, err := newLockFile(s.lockPath)
	if err != nil {
		return fmt.Errorf("creating lock: %w", err)
	}
	defer lock.Unlock()

	if err := lock.TryLock(); err != nil {
		return s.appendEntriesWithRetry(entries, 3)
	}

	return s.appendEntriesLine(entries)
}

func (s *IndexStore) appendEntriesLine(entries []PromptEntry) error {
	f, err := os.OpenFile(s.indexPath, os.O_APPEND|os.O_CREATE|os.O_WRONLY, 0o644)
	if err != nil {
		return fmt.Errorf("opening index for append: %w", err)
	}
	defer f.Close()

	for _, entry := range entries {
		data, err := json.Marshal(entry)
		if err != nil {
			return fmt.Errorf("marshaling entry: %w", err)
		}
		if _, err := f.Write(append(data, '\n')); err != nil {
			return fmt.Errorf("appending to index: %w", err)
		}
	}
	return nil
}

func (s *IndexStore) appendEntriesWithRetry(entries []PromptEntry, maxRetries int) error {
	var lastErr error
	for i := 0; i < maxRetries; i++ {
		time.Sleep(50 * time.Millisecond)

		lock, err := newLockFile(s.lockPath)
		if err != nil {
			lastErr = err
			continue
		}
		defer lock.Unlock()

		if err := lock.TryLock(); err != nil {
			lastErr = err
			continue
		}

		if err := s.appendEntriesLine(entries); err != nil {
			lastErr = err
			continue
		}
		return nil
	}
	return fmt.Errorf("failed to acquire lock after %d retries: %w", maxRetries, lastErr)
}

func (s *IndexStore) InitIndex() error {
	if err := os.MkdirAll(filepath.Dir(s.indexPath), 0o750); err != nil {
		return fmt.Errorf("creating index directory: %w", err)
	}

	header := IndexHeader{
		Version:   CurrentIndexVersion,
		CreatedAt: time.Now(),
		RepoRoot:  s.repoRoot,
	}

	data, err := json.Marshal(header)
	if err != nil {
		return fmt.Errorf("marshaling header: %w", err)
	}

	if err := os.WriteFile(s.indexPath, append(data, '\n'), 0o644); err != nil {
		return fmt.Errorf("writing index header: %w", err)
	}

	return nil
}

type IndexStats struct {
	IndexPath        string
	Version          int
	CheckpointCount  int
	PromptCount      int
	EmptyCount       int
	FileSize         int64
	LastUpdated      time.Time
	Exists           bool
}

func (s *IndexStore) Stats(_ context.Context) (IndexStats, error) {
	stats := IndexStats{
		IndexPath: s.indexPath,
		Exists:    s.Exists(),
	}

	if !stats.Exists {
		return stats, nil
	}

	fi, err := os.Stat(s.indexPath)
	if err == nil {
		stats.FileSize = fi.Size()
		stats.LastUpdated = fi.ModTime()
	}

	_, entries, err := s.Load(context.Background())
	if err != nil {
		if errors.Is(err, ErrIndexMissing) || errors.Is(err, ErrIndexEmpty) {
			return stats, nil
		}
		return stats, err
	}

	stats.PromptCount = len(entries)

	cpIDs := make(map[string]bool)
	for _, e := range entries {
		cpIDs[e.CheckpointID] = true
	}
	stats.CheckpointCount = len(cpIDs)
	stats.EmptyCount = len(entries) - stats.CheckpointCount

	return stats, nil
}

var checkpointIDPrefixRegex = regexp.MustCompile(`^[0-9a-f]{4,12}`)

func ParseCheckpointIDPrefix(prefix string) string {
	prefix = strings.TrimSpace(prefix)
	matches := checkpointIDPrefixRegex.FindString(prefix)
	if len(matches) < 4 {
		return ""
	}
	return matches
}

func FormatFileSize(bytes int64) string {
	if bytes < 1024 {
		return strconv.FormatInt(bytes, 10) + " B"
	}
	if bytes < 1024*1024 {
		return fmt.Sprintf("%.1f KB", float64(bytes)/1024)
	}
	if bytes < 1024*1024*1024 {
		return fmt.Sprintf("%.1f MB", float64(bytes)/(1024*1024))
	}
	return fmt.Sprintf("%.1f GB", float64(bytes)/(1024*1024*1024))
}

type fileLock struct {
	path string
	file *os.File
}

func newLockFile(path string) (*fileLock, error) {
	dir := filepath.Dir(path)
	if err := os.MkdirAll(dir, 0o750); err != nil {
		return nil, err
	}
	return &fileLock{path: path}, nil
}

func (l *fileLock) TryLock() error {
	f, err := os.OpenFile(l.path, os.O_CREATE|os.O_EXCL|os.O_WRONLY, 0o644)
	if err != nil {
		return err
	}
	l.file = f
	return nil
}

func (l *fileLock) Unlock() error {
	if l.file == nil {
		return nil
	}
	_ = l.file.Close()
	_ = os.Remove(l.path)
	l.file = nil
	return nil
}

func (s *IndexStore) Rebuild() error {
	if err := s.InitIndex(); err != nil {
		return err
	}
	return nil
}

package index

import (
	"context"
	"encoding/json"
	"fmt"
	"io"
	"strconv"
	"strings"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/checkpoint"
	"github.com/entireio/cli/cmd/entire/cli/checkpoint/id"
	"github.com/entireio/cli/cmd/entire/cli/paths"

	"github.com/go-git/go-git/v6"
	"github.com/go-git/go-git/v6/plumbing"
	"github.com/go-git/go-git/v6/plumbing/filemode"
)

const MaxPromptLength = 2000

type IndexBuilder struct {
	repo  *git.Repository
	store *IndexStore
}

func NewIndexBuilder(repo *git.Repository, store *IndexStore) *IndexBuilder {
	return &IndexBuilder{repo: repo, store: store}
}

func (b *IndexBuilder) AppendCheckpoint(_ context.Context, cpID id.CheckpointID, commitHash, commitMsg, branch, agent, model string, filesTouched []string, sessionIdx, turnIdx int, promptText string) error {
	truncated := false
	if len(promptText) > MaxPromptLength {
		promptText = promptText[:MaxPromptLength]
		truncated = true
	}

	entry := PromptEntry{
		CheckpointID:    cpID.String(),
		SessionIndex:    sessionIdx,
		TurnIndex:       turnIdx,
		Kind:            "session",
		PromptText:      promptText,
		PromptTruncated: truncated,
		CommitHash:      commitHash,
		CommitMessage:   commitMsg,
		Branch:          branch,
		Agent:           agent,
		Model:           model,
		FilesTouched:    filesTouched,
		CreatedAt:       time.Now(),
	}

	if err := b.store.AppendEntries([]PromptEntry{entry}); err != nil {
		return fmt.Errorf("appending entry: %w", err)
	}

	return nil
}

func (b *IndexBuilder) Build(_ context.Context, out io.Writer, progress func(done, total int)) error {
	if err := b.store.InitIndex(); err != nil {
		return fmt.Errorf("initializing index: %w", err)
	}

	ref, err := b.repo.Reference(plumbing.NewBranchReferenceName(paths.MetadataBranchName), true)
	if err != nil {
		return fmt.Errorf("getting metadata branch: %w", err)
	}

	commit, err := b.repo.CommitObject(ref.Hash())
	if err != nil {
		return fmt.Errorf("getting commit: %w", err)
	}

	tree, err := commit.Tree()
	if err != nil {
		return fmt.Errorf("getting tree: %w", err)
	}

	var cpIDs []id.CheckpointID
	_ = walkCheckpointShards(b.repo, tree.ID(), func(cpID id.CheckpointID, _ plumbing.Hash) error {
		cpIDs = append(cpIDs, cpID)
		return nil
	})

	total := len(cpIDs)
	allEntries := make([]PromptEntry, 0)

	for i, cpID := range cpIDs {
		entries, _ := b.loadCheckpoint(cpID)
		allEntries = append(allEntries, entries...)
		if progress != nil {
			progress(i+1, total)
		}
	}

	header := IndexHeader{
		Version:   CurrentIndexVersion,
		CreatedAt: time.Now(),
		RepoRoot:  b.store.repoRoot,
	}

	_ = header

	fmt.Fprintf(out, "Indexed %d prompts from %d checkpoints.\n", len(allEntries), total)

	return nil
}

func isHex(s string) bool {
	for _, c := range s {
		if !((c >= '0' && c <= '9') || (c >= 'a' && c <= 'f')) {
			return false
		}
	}
	return true
}

func walkCheckpointShards(repo *git.Repository, treeHash plumbing.Hash, fn func(id.CheckpointID, plumbing.Hash) error) error {
	rootTree, err := repo.TreeObject(treeHash)
	if err != nil {
		return fmt.Errorf("getting tree: %w", err)
	}

	for _, shardEntry := range rootTree.Entries {
		entryMode := filemode.FileMode(shardEntry.Mode)
		if entryMode != filemode.Dir || len(shardEntry.Name) != 2 || !isHex(shardEntry.Name) {
			continue
		}

		shardTree, err := repo.TreeObject(shardEntry.Hash)
		if err != nil {
			continue
		}

		for _, cpEntry := range shardTree.Entries {
			cpMode := filemode.FileMode(cpEntry.Mode)
			if cpMode != filemode.Dir || len(cpEntry.Name) != 10 || !isHex(cpEntry.Name) {
				continue
			}

			fullID := shardEntry.Name + cpEntry.Name
			cpID, err := id.NewCheckpointID(fullID)
			if err != nil {
				continue
			}

			if err := fn(cpID, cpEntry.Hash); err != nil {
				return err
			}
		}
	}

	return nil
}

type SessionData struct {
	Prompts []string
}

func (b *IndexBuilder) loadCheckpoint(cpID id.CheckpointID) ([]PromptEntry, error) {
	shard := cpID.String()[:2]
	rest := cpID.String()[2:]
	cpDir := filepath.Join(shard, rest, "0")

	ref, err := b.repo.Reference(plumbing.NewBranchReferenceName(paths.MetadataBranchName), true)
	if err != nil {
		return nil, err
	}

	commit, err := b.repo.CommitObject(ref.Hash())
	if err != nil {
		return nil, err
	}

	tree, err := commit.Tree()
	if err != nil {
		return nil, err
	}

	cpTree, err := tree.Tree(cpDir)
	if err != nil {
		return nil, err
	}

	metaFile, err := cpTree.File("metadata.json")
	if err != nil {
		return nil, err
	}

	metaContent, err := metaFile.Contents()
	if err != nil {
		return nil, err
	}

	var metadata checkpoint.CheckpointSummary
	if err := json.Unmarshal([]byte(metaContent), &metadata); err != nil {
		return nil, err
	}

	promptFile, err := cpTree.File("prompt.txt")
	var promptContent string
	if err == nil {
		promptContent, _ = promptFile.Contents()
	}

	entries := make([]PromptEntry, 0)
	for i, session := range metadata.Sessions {
		prompts := splitPrompts(promptContent)
		prompt := ""
		if i < len(prompts) {
			prompt = prompts[i]
		}
		if prompt == "" {
			prompt = session.Prompt
		}

		truncated := false
		if len(prompt) > MaxPromptLength {
			prompt = prompt[:MaxPromptLength]
			truncated = true
		}

		entry := PromptEntry{
			CheckpointID:    cpID.String(),
			SessionIndex:    i,
			TurnIndex:       0,
			Kind:            "session",
			PromptText:      prompt,
			PromptTruncated: truncated,
			Agent:           session.Agent,
			Model:           session.Model,
			FilesTouched:    session.FilesTouched,
		}

		entries = append(entries, entry)
	}

	return entries, nil
}

func splitPrompts(promptContent string) []string {
	if promptContent == "" {
		return nil
	}

	result := strings.Split(promptContent, "---\n\n")
	if len(result) == 0 {
		return []string{promptContent}
	}
	return result
}

